Node.js API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Node.js API Gateway container

Container_Boundary(node_js_api_gateway, "Node.js API Gateway") {
    Component(FastifyRoutingEngine, "Fastify Routing Engine", "Node.js, Fastify", "High-throughput API gateway runtime and routing engine.")
    Component(HTTPProxyMiddleware, "HTTP Proxy Middleware", "http-proxy-middleware", "Proxies incoming client requests to downstream microservices.")
    Component(CircuitBreakerManager, "Circuit Breaker Manager", "opossum", "Implements circuit breaker pattern for rural connection resilience.")
}

Rel(FastifyRoutingEngine, HTTPProxyMiddleware, "Routes incoming traffic")
Rel(HTTPProxyMiddleware, CircuitBreakerManager, "Wraps downstream calls with resilience patterns")

@enduml

Go Consent & Localization Engine.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Go Consent & Localization Engine container

Container_Boundary(go_consent_localization_engine, "Go Consent & Localization Engine") {
    Component(Consent_Manager, "Consent Manager", "Go", "Manages patient consent records and compliance verification across jurisdictions.")
    Component(Localization_Engine, "Localization Engine", "Go", "Handles regional language, timezone, and regulatory localization rules.")
    Component(Audit_Logger, "Audit Logger", "Go", "Records access and consent changes for regulatory auditing purposes.")
}

Rel(Consent_Manager, Localization_Engine, "Queries localization rules for specific jurisdictions")
Rel(Consent_Manager, Audit_Logger, "Logs consent transactions")

@enduml

US HL7 FHIR Adapters.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(us_hl7_fhir_adapters, "US HL7 FHIR Adapters") {
    Component(FHIR_Resource_Mapper, "FHIR Resource Mapper", "Go / Python", "Transforms internal data models to and from HL7 FHIR standard formats.")
    Component(Client_Connection_Pooler, "Client Connection Pooler", "Go", "Manages outbound mTLS connections and connection pooling to external US HL7 FHIR Engines.")
    Component(Terminology_Translator, "Terminology Translator", "Python / Rust", "Translates medical terminologies and codes for US healthcare system interoperability.")
}

Rel(Client_Connection_Pooler, FHIR_Resource_Mapper, "Provides mapped FHIR resources over internal channels")
Rel(FHIR_Resource_Mapper, Terminology_Translator, "Requests code and terminology translations")

@enduml
